{
 "initial_node": "setup",
 "system_prompt": "You are the automated assistant of Example Bank, calling a customer. Speak English, one or two short sentences per turn. Never mention money, an item or the reason for the call before identity is confirmed. Never invent amounts, dates or terms: use only the facts you are given. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
 "test_variables": {
  "customer_id": "c_demo",
  "first_name": "Sam",
  "last_name": "Doe",
  "title": "Mx",
  "now": "2031-03-07T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "opening",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\n\ndef parse_now(value):\n    \"\"\"'2031-03-07T11:00', '2031-03-07 11:00:00', '2031-03-07T11:00:00Z' or '2031-03-07' -> datetime.\"\"\"\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now: ' + s)\n\ndef parse_holidays(values):\n    \"\"\"ISO strings -> set of dates. Unreadable entries are skipped.\"\"\"\n    out = set()\n    for v in values or []:\n        try:\n            out.add(datetime.date.fromisoformat(str(v)[:10]))\n        except ValueError:\n            pass\n    return out\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    \"\"\"The first business day after d (or d itself when include_today and d is one).\"\"\"\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken_date(d):\n    \"\"\"'Friday 7 March'. Adapt the words to the brief's language.\"\"\"\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ntry:\n    now = parse_now(vars.get('now'))\n    hol = parse_holidays(['2031-03-14', '2031-04-02'])\n    today = now.date()\n    vars['today_spoken'] = spoken_date(today)\n    nxt = next_business_day(today, hol)\n    same_day = 'yes' if is_business_day(today, hol) and now.hour < 17 else 'no'\n    days = ('today (' + spoken_date(today) + ') after ' + now.strftime('%H:%M') + ' and ') if same_day == 'yes' else ''\n    vars['callback_window_text'] = 'A callback can be booked ' + days + 'on ' + spoken_date(nxt) + ', from 09:00 to 17:00. Today is ' + spoken_date(today) + ', ' + now.strftime('%H:%M') + '.'\n    vars['callback_next_day_iso'] = nxt.isoformat()\n    vars['calendar_state'] = 'ok'\nexcept Exception:\n    vars['today_spoken'] = ''\n    vars['callback_window_text'] = 'Ask for a time tomorrow between 09:00 and 17:00.'\n    vars['calendar_state'] = 'error'\nvars['close_outcome'] = 'outcome_w'\nvars['close_detail'] = 'detail_c'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "opening",
     "description": "always",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
  "opening": {
   "name": "opening",
   "node_type": "conversation",
   "on_enter": {
    "type": "tts",
    "text": "Hello, this is the automated assistant of Example Bank, and this call is recorded. Am I speaking with {{title}} {{last_name}}?"
   },
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only a clear yes or their own name confirms it. If the answer is unclear, ask once more. Say nothing about why you are calling. No tool call is allowed in this turn.",
   "extraction_schema": [
    {
     "name": "who",
     "type": "string",
     "enum_values": [
      "customer",
      "someone_else",
      "not_their_line",
      "unclear"
     ],
     "description": "Who answered: customer (clear yes or own name), someone_else, not_their_line, unclear.",
     "min_confidence": 0.6
    }
   ],
   "max_node_turns": 3,
   "max_turn_transition": "goodbye_short",
   "transitions": [
    {
     "target_node": "identity",
     "description": "The customer confirmed",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "who",
        "operator": "equals",
        "operand": "customer"
       }
      ]
     }
    },
    {
     "target_node": "third_party_prep",
     "description": "Someone else answered",
     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "who",
        "operator": "equals",
        "operand": "someone_else"
       }
      ]
     }
    },
    {
     "target_node": "mark_not_their_line",
