     "condition": {
      "logic": "or",
      "conditions": [
       {
        "variable": "who",
        "operator": "equals",
        "operand": "not_their_line"
       }
      ]
     }
    }
   ]
  },
  "mark_not_their_line": {
   "name": "mark_not_their_line",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "goodbye_short",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "try:\n    vars['close_outcome'] = 'outcome_w'\n    vars['close_detail'] = 'detail_b'\nexcept Exception:\n    pass\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "goodbye_short",
     "description": "always",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
  "third_party_prep": {
   "name": "third_party_prep",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "third_party",
   "on_enter": {
    "type": "silent"
   },
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {
         "type": "string",
         "default": "try:\n    vars['close_outcome'] = 'outcome_w'\n    vars['close_detail'] = 'detail_d'\nexcept Exception:\n    pass\n"
        },
        "timeout_ms": {
         "type": "number",
         "default": 10000
        }
       }
      }
     }
    }
   ],
   "transitions": [
    {
     "target_node": "third_party",
     "description": "always",
     "condition": {
      "operator": "always"
     }
    }
   ]
  },
  "third_party": {
   "name": "third_party",
   "node_type": "conversation",
   "task_message": "You are not speaking with the customer. Do not say why you are calling. Ask when {{title}} {{last_name}} can be reached. {{callback_window_text}} When they give a time inside that window, call schedule_callback with it. If the time is outside it, ask once for another. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
   "tools": [
    {
     "type": "function",
     "config": {
      "timeoutMs": 12000,
      "maxRetries": 0
     },
     "function": {
      "name": "schedule_callback",
      "handler": "__function__:api_call",
      "description": "Book the callback. CALL it as soon as the person gives a time inside the window.",
      "parameters": {
       "type": "object",
       "properties": {
        "url": {
         "type": "string",
         "default": "https://api.example-bank.invalid/v1/schedule_callback"
        },
        "method": {
         "type": "string",
         "default": "POST"
        },
        "headers": {
         "type": "object",
         "properties": {
          "Content-Type": {
           "type": "string",
           "default": "application/json"
          }
         }
        },
        "body": {
         "type": "object",
         "properties": {
          "customer_id": {
           "type": "string",
           "default": "{{customer_id}}"
          },
          "slot": {
           "type": "string",
           "description": "Agreed time as YYYY-MM-DDTHH:MM, inside the window.",
           "default": "{{slot}}"
          }
         },
         "required": [
          "customer_id",
          "slot"
         ]
        }
       }
      }
     },
     "pre_process_code": "try:\n    b = config.get('body')\n    if isinstance(b, dict) and isinstance(b.get('slot'), str):\n        b['slot'] = b['slot'].strip().replace(' ', 'T')[:16]\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['close_detail'] = 'detail_a'\n        vars['call_state'] = 'callback_booked'\n        d['what_to_do_next'] = 'Booked. Thank them and say goodbye.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'Not booked. Ask once for another time inside the window.'\nexcept Exception:\n    pass\n"
    }
   ],
   "extraction_schema": [
    {
     "name": "third_party_done",
     "type": "string",
     "enum_values": [
      "stay",
      "no_time"
     ],
     "description": "no_time when the person gave no time inside the window after the second ask, else stay.",
     "min_confidence": 0.7
    }
   ],
   "max_node_turns": 6,
   "max_turn_transition": "goodbye_short",
   "transitions": [
    {
     "target_node": "goodbye_short",
     "description": "Callback booked",
     "condition": {
      "logic": "or",
      "conditions": [
