        floor_name = 'one instalment'
    past_due = float(p.get('past_due') or 0)
    days = int(float(p.get('days_late') or 0))
    if days <= 7:
        band, n_bd, attempts = 'early', 12, 1
    else:
        band, n_bd, attempts = 'late', 7, 2
    deadline = add_bd(today, n_bd)
    wk = last_bd_of_week(today)
    if wk is None or wk <= today:
        wk = last_bd_of_week(today + datetime.timedelta(days=7))
    a1 = min(wk, deadline)
    first_ok = next_bd(today, True)
    rows = []
    for i in range(0, 29):
        d = today + datetime.timedelta(days=i)
        if d > deadline + datetime.timedelta(days=7):
            break
        if not is_bd(d):
            status = 'NOT a business day' + (' (holiday)' if d in HOL else '') + ': offer ' + spoken(next_bd(d)) + ' instead' + ('' if next_bd(d) <= deadline else ' -- but that is after the deadline, so offer the deadline')
        elif d > deadline:
            status = 'after the deadline: offer the deadline instead'
        else:
            status = 'OK to record'
        rel = ''
        if d.weekday() < 7:
            if week_monday(d) == week_monday(today):
                rel = ' [this ' + WEEKDAYS[d.weekday()].title() + ']'
            elif week_monday(d) == week_monday(today) + datetime.timedelta(days=7):
                rel = ' [next ' + WEEKDAYS[d.weekday()].title() + ']'
        rows.append('- ' + spoken(d) + ' ' + str(d.year) + ' (' + d.isoformat() + ')' + rel + ': ' + status)
    pd = money(past_due)
    fl = money(floor)
    vars['product_id'] = str(p.get('product_id') or '')
    vars['product_label'] = label
    vars['past_due_text'] = pd
    vars['days_late_text'] = str(days)
    vars['attempts_allowed'] = str(attempts)
    vars['deadline_iso'] = deadline.isoformat()
    vars['offer_attempt1_full'] = 'Could you pay the full past-due amount of ' + pd + ' by ' + spoken(a1) + '?'
    vars['offer_attempt1_floor'] = 'Could you pay ' + fl + ', ' + floor_name + ', by ' + spoken(a1) + '? The rest stays overdue.'
    vars['offer_attempt2'] = 'Could you pay ' + fl + ', ' + floor_name + ', by ' + spoken(deadline) + '? The rest stays overdue.'
    vars['offer_floor'] = 'I can offer a lower amount: ' + fl + ', ' + floor_name + '. The rest stays overdue. Can you pay that today?'
    vars['offer_deadline'] = 'The latest date I can record is ' + spoken(deadline) + '. Can you pay by then?'
    vars['facts_text'] = ('Today is ' + spoken(today) + ' ' + str(today.year) + ' (' + today.isoformat() + ').\n' +
