import datetime
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def norm_dob(text):
    s = str(text or '').strip().lower()
    m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})$', s)
    if m:
        return '%04d-%02d-%02d' % (int(m.group(1)), int(m.group(2)), int(m.group(3)))
    month = None
    for i, name in enumerate(MONTHS):
        if re.search(r'\b' + name[:3] + r'[a-z]*\b', s):
            month = i + 1
            s = re.sub(r'\b' + name[:3] + r'[a-z]*\b', ' ', s)
            break
    nums = re.findall(r'\d+', s)
    if month is not None:
        year = next((int(n) for n in nums if len(n) == 4), None)
        day = next((int(n) for n in nums if len(n) <= 2), None)
        if year and day:
            return '%04d-%02d-%02d' % (year, month, day)
        return text
    if len(nums) == 3:
        a, b, c = nums
        if len(a) == 4:
            return '%04d-%02d-%02d' % (int(a), int(b), int(c))
        y = int(c)
        if y < 100:
            y = y + 1900 if y > 30 else y + 2000
        return '%04d-%02d-%02d' % (y, int(b), int(a))
    if len(nums) == 1 and len(nums[0]) == 8:
        n = nums[0]
        return n[4:] + '-' + n[2:4] + '-' + n[:2]
    return text

