        if not is_bd(d):
            status = 'NOT a business day' + (' (holiday)' if d in HOL else '') + ': offer ' + spoken(next_bd(d)) + ' instead' + ('' if next_bd(d) <= deadline else ' -- but that is after the deadline, so offer the deadline')
        elif d > deadline:
            status = 'after the deadline: offer the deadline instead'
        else:
