    vars['product_label'] = label
    vars['past_due_text'] = pd
    vars['days_late_text'] = str(days)
    vars['attempts_allowed'] = str(attempts)
    vars['deadline_iso'] = deadline.isoformat()
    vars['offer_attempt1_full'] = 'Could you pay the full past-due amount of ' + pd + ' by ' + spoken(a1) + '?'
    vars['offer_attempt1_floor'] = 'Could you pay ' + fl + ', ' + floor_name + ', by ' + spoken(a1) + '? The rest stays overdue.'
    vars['offer_attempt2'] = 'Could you pay ' + fl + ', ' + floor_name + ', by ' + spoken(deadline) + '? The rest stays overdue.'
    vars['offer_floor'] = 'I can offer a lower amount: ' + fl + ', ' + floor_name + '. The rest stays overdue. Can you pay that today?'
