    vars['facts_text'] = ('Today is ' + spoken(today) + ' ' + str(today.year) + ' (' + today.isoformat() + ').\n' +
        'Product: ' + label + ' (product_id ' + vars['product_id'] + '). Past-due amount: ' + pd + '. Days late: ' + str(days) + '.\n' +
        'Full amount: ' + pd + '. Lowest amount you may accept (the floor, ' + floor_name + '): ' + fl + '. Any amount from ' + fl + ' to ' + pd + ', both included, can be recorded. Below ' + fl + ': say it cannot be recorded and offer the floor once.\n' +
